ST.xhtml:p:
Rtrig_EndCutEnable(CLK := (g_nLayerStart =500 AND g_biPerfectEndCutEnableM62P9));
(*慢速起刀功能*)
IF g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.nSlowStartCutEnable = 1 THEN
  g_bSlowStartCutOpen := TRUE;
ELSE
  g_bSlowStartCutOpen := FALSE;
END_IF;
g_dSlowStartCutDis := g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.dSlowStartCutDis;
g_dSlowSpeedRatio := g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.dSpeedRatio;
bPrefectEndCutControlOpen := g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.bPrefectEndCutEnable;
bSlowStartCutControlOpen := g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.bSlowStartControlOpen;
g_foEndCutSpeed := (g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.dPrefectEndCutVel/60.0)*1000.0; (*完美收刀速度  现在准备改成直接发给CNC cnc自己规划 需要的单位是MM/S 界面上下发的是M/min*)
IF g_dSlowSpeedRatio <= 5.0 THEN  (*HMI慢速起刀速度倍率*)
  g_dSlowSpeedRatio := 5.0;
END_IF;
Rtrig_SlowCutState(CLK := (g_nLayerStart =500 AND g_bSlowStartCutOpen));
IF Rtrig_SlowCutState.Q THEN
  nSlowCutState := 10;
   GoneDist := 0.0;
   g_dSlowStartGoneDist :=0.0;
	IF Rtrig_EndCutEnable.Q THEN
      nSlowCutState := 15;
    END_IF;
END_IF;
IF Rtrig_EndCutEnable.Q THEN
  g_dGoneDist :=0.0;
  nSlowCutState := 15;
END_IF;
IF g_bChangeSecondFlyAndPowerCutCommunicationCycle THEN
  fActualCommunicationCycle := g_fSecondCommunicationCycle;
ELSE
  fActualCommunicationCycle := g_fCommunicationCycle;
END_IF;
CASE nSlowCutState OF
  0:(*关闭慢速起刀速度倍率*)
	nSlowCutState := 0;
  10: 
	 GoneDist := GoneDist + g_fiXYCurrentSpeedBuff *0.001;(**速度乘以周期就是移动的距离**)
    (*当移动距离小于等于慢速起刀距离时，开启慢速起刀速度倍率功能*)
    g_doRealtimeOverrid := g_dSlowSpeedRatio/100.0;
    g_boSlowcutEnable := TRUE;
    g_bIsSetSlowCutEnableFlag := TRUE; 
    Timer_EndCut(IN := FALSE);   
    IF GoneDist >= g_dSlowStartCutDis THEN
      GoneDist := 0.0;
      g_boSlowcutEnable := FALSE;
      g_bIsSetSlowCutEnableFlag := FALSE;       
      nSlowCutState := 0;       
    ELSIF g_nLayerStart <> 500 THEN    (*不在切割中*)
		nSlowCutState := 0;
		g_boSlowcutEnable := FALSE;
    END_IF;
    IF GoneDist < g_dSlowStartCutDis AND g_nLayerStart = 500 AND bSlowStartCutControlOpen THEN

      SlowStartCutPwmControl();
    END_IF;
    IF Rtrig_EndCutEnable.Q THEN    (*当收到的收刀信号 M62 P9，开启收刀速度倍率功能  收刀优先*)
      nSlowCutState := 15;
    END_IF;
  15:
	 Timer_EndCut(IN := TRUE,PT := LREAL_TO_TIME((fActualCommunicationCycle+20.0)/1000.0));  (*功率控制周期加20才准*)
	   IF Timer_EndCut.Q THEN
		  Timer_EndCut(IN := FALSE);
		  nSlowCutState := 20;
	   END_IF;
  20:
	Timer_EndCut(IN := FALSE);
    IF (g_nLayerStart <> 500) OR (NOT  g_biPerfectEndCutEnableM62P9)  THEN    (*不在切割中 或者M69P5已经触发了之前这个条件不OR上的话会导致飞切微联加上收刀在微联之后就不出光 *)

      nSlowCutState := 0;
    g_boSlowcutEnable := FALSE;
    END_IF;
    IF g_nLayerStart = 500 AND bPrefectEndCutControlOpen THEN (*加工过程中的收刀工艺才需要生效*)
      EndCutPwmControl();
    END_IF; 
END_CASE;

IF (NOT  g_biPerfectEndCutEnableM62P9)  THEN
  g_dGoneDist :=0.0;
END_IF;

g_doSlowStartGoneDist := g_dSlowStartGoneDist;
